∀ {α : Type u} [inst : BEq α] [LawfulBEq α] (pattern : List α) (q : ℕ) (hq : q < pattern.length),
  let table := pattern.toArray.mkPrefixTable;
  have failure := table.toArray[q].2;
  failure ≤ q ∧ List.take failure pattern <:+ List.take (q + 1) pattern ∧ ∀ k ≤ q, List.take k pattern <:+ List.take (q + 1) pattern → k ≤ failure

∀ {α : Type u} [inst : BEq α] [LawfulBEq α] (pattern consumed : List α) (x : α) (state : Fin (pattern.toArray.mkPrefixTable.size + 1)),
  (↑state ≤ pattern.length ∧ List.take (↑state) pattern <:+ consumed ∧ ∀ k ≤ pattern.length, List.take k pattern <:+ consumed → k ≤ ↑state) →
    let table := pattern.toArray.mkPrefixTable;
    have next := table.step x state;
    ↑next ≤ pattern.length ∧ List.take (↑next) pattern <:+ consumed ++ [x] ∧ ∀ k ≤ pattern.length, List.take k pattern <:+ consumed ++ [x] → k ≤ ↑next

∀ (n : ℕ) (edges : List (Fin n × Fin n)),
  have graph := SimpleGraph.fromEdgeSet {e | e ∈ List.map (fun p ↦ s(p.1, p.2)) edges};
  (Batteries.UnionFind.connectedComponents n edges).time = (n, 2 * edges.length, n - Nat.card graph.ConnectedComponent) ∧ Nat.card graph.ConnectedComponent + (Batteries.UnionFind.connectedComponents n edges).time.2.2 = n ∧ (0 < n → (Batteries.UnionFind.connectedComponents n edges).time.2.2 ≤ n - 1)

