∀ {α : Type u} {capacity : ℕ} (store : Vector (Option (Cslib.Algorithms.Lean.DoublyLinkedList.Node α (Fin capacity))) capacity) (head : Option (Fin capacity)) (x : Fin capacity) (hx : (store.get x).isSome = Bool.true) (hp : ∀ (p : Fin capacity), ((store.get x).get hx).prev = Option.some p → (store.get p).isSome = Bool.true) (hn : ∀ (n : Fin capacity), ((store.get x).get hx).next = Option.some n → (store.get n).isSome = Bool.true) (z : Fin capacity),
  (Cslib.Algorithms.Lean.DoublyLinkedList.listDelete store head x hx hp hn).ret.1.get z =
    have originalX := (store.get x).get hx;
