  (∀ (a : α) (b : β), 0 < p a b) →
    ∑ a, ∑ b, p a b = 1 →
      ∀ (g : β → α),
        2 ≤ Fintype.card α →
          have pY := fun y ↦ ∑ a, p a y;
          have Pe := ∑ b, ∑ a, if g b ≠ a then p a b else 0;
          have HXY := -∑ a, ∑ b, p a b * Real.log (p a b / pY b);
